cypress_script:
describe('Horizontal Range Slider Control', () => {
  it('should update the value when slider is moved (happy path)', () => {
    cy.visit('https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('input[type="range"]').invoke('val', 5).trigger('input');
    cy.get('span#range').should('have.text', '5');
  });

  it('should not change URL when slider is moved (edge case)', () => {
    cy.visit('https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('input[type="range"]').invoke('val', 10).trigger('input');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('span#range').should('have.text', '10');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Horizontal Range Slider Control', () => {
  test('should update the value when slider is moved (happy path)', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/horizontal_slider');
    await page.locator('input[type="range"]').fill('5');
    await page.locator('input[type="range"]').dispatchEvent('input');
    await expect(page.locator('span#range')).toHaveText('5');
  });

  test('should not change URL when slider is moved (edge case)', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/horizontal_slider');
    await page.locator('input[type="range"]').fill('10');
    await page.locator('input[type="range"]').dispatchEvent('input');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/horizontal_slider');
    await expect(page.locator('span#range')).toHaveText('10');
  });
});
